// HasWorkspace applies the HasEdge predicate on the "workspace" edge.
func HasWorkspace() predicate.BroadcastFigure {
	return predicate.BroadcastFigure(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, WorkspaceTable, WorkspaceColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkspaceWith applies the HasEdge predicate on the "workspace" edge with a given conditions (other predicates).
func HasWorkspaceWith(preds ...predicate.Workspace) predicate.BroadcastFigure {
	return predicate.BroadcastFigure(func(s *sql.Selector) {
		step := newWorkspaceStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasBroadcast applies the HasEdge predicate on the "broadcast" edge.
func HasBroadcast() predicate.BroadcastFigure {
	return predicate.BroadcastFigure(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, BroadcastTable, BroadcastColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBroadcastWith applies the HasEdge predicate on the "broadcast" edge with a given conditions (other predicates).
func HasBroadcastWith(preds ...predicate.Broadcast) predicate.BroadcastFigure {
	return predicate.BroadcastFigure(func(s *sql.Selector) {
		step := newBroadcastStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BroadcastFigure) predicate.BroadcastFigure {
	return predicate.BroadcastFigure(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BroadcastFigure) predicate.BroadcastFigure {
	return predicate.BroadcastFigure(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BroadcastFigure) predicate.BroadcastFigure {
	return predicate.BroadcastFigure(sql.NotPredicates(p))
}
